 */
#include <stdio.h>

int largest(int *arr, int n);

int main(void) {
    int arr[100];
    int n, i;

    printf("Enter number of elements (max 100): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        printf("Invalid size\n");
        return 1;
    }

    printf("Enter %d integers: ", n);
    for (i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    printf("Largest element = %d\n", largest(arr, n));
    return 0;
}

