    arr = temp;

    printf("Enter %d more integers: ", extra);
    for (i = n; i < n + extra; i++) {
        scanf("%d", &arr[i]);
    }
    n += extra;

    printf("Array after realloc (%d elements): ", n);
    for (i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    free(arr);
    arr = NULL;
    return 0;
}
